update tax_rate set headline_rate = 0.2, rate_min = 0.2, rate_max = 0.2, threshold_amount = null, threshold_note = null, note = 'Stamp duty (imposta di bollo) on financial investments held in Italy: 0.2% a year of their value at 31 December (PwC Other taxes, last reviewed 16 Sep 2019). The copy dated in 2019 still labels the rate "for FY 2018"; EY Worldwide Personal Tax Guide 2015-16 (content current on 1 July 2015): IVAFE "The tax rate is 0.20% from 2014 onward" for the same rate on assets held abroad. Financial investments held abroad pay IVAFE at the same 0.2% instead, so the rate is the same either way.', source_url = 'https://web.archive.org/web/20191213173003/http://taxsummaries.pwc.com:80/ID/Italy-Individual-Other-taxes', verified_on = '2019-12-13', next_check_on = '2027-01-15', needs_verification = false, valid_to = '2020-01-01' where jurisdiction_code = 'IT' and tax_type_code = 'SECURITIES_ACCOUNT' and valid_from = '2019-01-01';
